modules-mod(wrap save-mods unwrap)(Module)((listp X ()))((listp X (Y|Z))  (LISTP X Y)  (listp X Z))((COPYRIGHT 1983 LPA LTD (V 6 -16)))((wrap X)  (DELCL ((Module Y Z x)))  (PP Saving module Y in file X)  (PP Start tape for recording)  (PP Hit ENTER key when)  (RFILL (ready) y)  (CREATE X)  (WRITE X (Y))  (WRITE X (Z))  (WRITE X (x))  (LISTP X)  (WRITE X (CLMOD))  (CLOSE X)  (DICT z X1 Y1|Z1)  (KILL Z1)  (PP Workspace is now clear))((save-mods X)  (R Y)  (save-mods X Y))((save-mods X Y)  (PP Start tape for recording)  (PP Hit ENTER when)  (RFILL (ready) Z)  (CREATE X)  (listp X Y)  (CLOSE X))((unwrap X)  (CON X)  (OPMOD X)  (DICT X Y Z|x)  (PP Unwrapping X onto scratch file)  (PP Start tape for recording)  (PP Hit ENTER key when)  (RFILL (ready) y)  (CREATE $$$$$$$$.###)  (WRITE $$$$$$$$.### (((Module X Y Z))))  (LISTP $$$$$$$$.###)  (CLOSE $$$$$$$$.###)  CLMOD  (KILL X)  (PP Rewind tape to start of saved program)  (PP Loading program from tape)  (LOAD $$$$$$$$.###)  (PP X is now in workspace))CLMOD